"""Controlled DOM metadata: explicit unused return, drafts and protected callers."""
import http.server,json,pathlib,sys,tempfile,threading,runpy
from playwright.sync_api import sync_playwright,expect
repo=pathlib.Path(sys.argv[1]).resolve();case=pathlib.Path(tempfile.mkdtemp(prefix='confectory-private-node-void-renderer-'));checks=[];errors=[]
class Handler(http.server.SimpleHTTPRequestHandler):
 def __init__(self,*a,**kw):super().__init__(*a,directory=str(repo),**kw)
 def log_message(self,*a):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);threading.Thread(target=server.serve_forever,daemon=True).start()
bootstrap=r"""async()=>{
 const {createFeatureAuthoring}=await import('/examples/editor-home/ui/feature-authoring.js');
 const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
 const contract={args:[{name:'amount',type:'long'},{name:'count',type:'long'}],return:'long'},native={args:[{name:'firstNative',type:'long'},{name:'secondNative',type:'long'}],return:'long'};
 const text='return Keep(firstNative+secondNative); // 한글 😀\r\n',helpers='static long Keep(long value){return value;}\r\n',row={hash:'a'.repeat(64),sourceKind:'scoped-code-csharp',caller:true,editableNativeNames:true,editableNativeTypes:[],editableNativeReturn:true,control:'next',helperEditor:true,signature:native,contractSignature:native,text,helpers,path:'private.node.json',whole:{node:'inner/body',hash:'b'.repeat(64)}},state={saved:{},drafts:JSON.parse(sessionStorage.aliasDrafts||'{}'),commits:[],toasts:[]};
 const controller=createFeatureAuthoring({$,$$,esc,authorInputs:new Map(),toast:t=>state.toasts.push(t),modal:(title,html,mount)=>{const root=document.createElement('section');root.setAttribute('role','dialog');root.innerHTML=html;document.body.append(root);mount(root,()=>root.remove());}});
 globalThis.fixture={state,row,contract,text,helpers,open:()=>controller.editInformationBodies({title:'부모 프레임 보존',rows:{body:row},contract,alive:()=>true,saved:state.saved,drafts:state.drafts,retain:(id,v)=>{state.drafts[id]=v;sessionStorage.aliasDrafts=JSON.stringify(state.drafts);},cancel:()=>{},commit:(id,v)=>state.commits.push(v)})};
}"""
def checked(label):checks.append(label);print('PASS '+label,flush=True)
def region(name,text):
 field=page.locator('[data-code-source]');field.evaluate('(el,name)=>{const s=[...el.closest(".bp-script-editor").querySelectorAll("[data-code-highlight]>span")],b=s.find(v=>v.dataset.codeRegion===name),start=s.slice(0,s.indexOf(b)).reduce((n,v)=>n+v.textContent.length,0);if(!b)throw Error("missing region");el.focus();el.setSelectionRange(start,start+b.textContent.length)}',name);page.keyboard.insert_text(text)
def plan():return json.loads(page.evaluate('()=>JSON.stringify(fixture.state.commits.at(-1))'))
try:
 with sync_playwright()as p:
  expect.set_options(timeout=10000);browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=browser.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:'+str(server.server_port)+'/');page.evaluate(bootstrap)
  page.evaluate('()=>fixture.open()');expect(page.locator('[data-code-region=returnType]')).to_have_count(1);region('returnType','void');page.locator('[data-code-save]').click();v=plan();assert v['signature']['return']=='void'and v['signature']['args']==v['beforeSignature']['args']and v['contract']==page.evaluate('()=>fixture.contract')and v['text']==page.evaluate('()=>fixture.text')and v['helpers']==page.evaluate('()=>fixture.helpers');checked('explicit return-only plan preserves exact source/helpers, parameters and parent ABI without generating conversions')
  page.evaluate('()=>{fixture.state.drafts={};fixture.open()}');region('returnType','void');region('body','if(firstNative==secondNative)throw new System.InvalidOperationException();return; // 직접 작성 😀\n');draft=page.evaluate('()=>fixture.state.drafts.body');page.reload();page.evaluate(bootstrap);page.evaluate('()=>fixture.open()');assert page.locator('[data-code-source]').input_value().startswith('public void Invoke(long firstNative, long secondNative)');page.locator('[data-code-save]').click();v=plan();assert v['text']==draft['text']and v['signature']['return']=='void'and v['beforeSignature']['return']=='long'and v['contract']==page.evaluate('()=>fixture.contract');checked('fresh DOM restores explicit return/body draft with original before-signature and separate parent contract')
  page.evaluate('(v)=>{fixture.state.saved={body:v};fixture.state.drafts={};fixture.open()}',v);assert page.locator('[data-code-source]').input_value().startswith('public void Invoke(');page.locator('[data-code-save]').click();assert plan()==v;checked('Code Save reentry retains the same explicit return and original graph/source plan before owner Save')
  for value,args in [('float','long firstNative, long secondNative'),('int','long firstNative, long secondNative'),('void','long renamedNative, long secondNative'),('void','long firstNative, double secondNative'),('void','long firstNative, ref long secondNative'),('void','long firstNative')]:
   page.evaluate('()=>{fixture.state.saved={};fixture.state.drafts={};fixture.open()}');region('returnType',value);region('parameters',args);count=page.evaluate('()=>fixture.state.commits.length');page.locator('[data-code-save]').click();expect(page.locator('[data-code-error]')).to_be_visible();assert page.evaluate('()=>fixture.state.commits.length')==count and page.evaluate('()=>fixture.state.drafts.body.returnType')==value and page.evaluate('()=>fixture.state.drafts.body.parameters')==args;page.locator('[data-code-cancel]').click();checked('unsupported/mixed return plan retains rejected user input '+value+' '+args)
  page.evaluate('()=>{fixture.state.saved={};fixture.state.drafts={};fixture.row.editableNativeReturn=false;fixture.open()}');expect(page.locator('[data-code-region=returnType]')).to_have_count(0);field=page.locator('[data-code-source]');old=field.input_value();field.evaluate("el=>{el.focus();el.setSelectionRange(el.value.indexOf('long'),el.value.indexOf('long')+4)}");page.keyboard.insert_text('void');assert field.input_value()==old;page.locator('[data-code-cancel]').click();checked('consumed or unselected return metadata keeps the original native return header protected')
  page.evaluate('()=>{fixture.row.editableNativeReturn=true;fixture.state.drafts={body:{hash:"f".repeat(64),text:"retained",returnType:"double"}};fixture.open()}');expect(page.locator('[role=dialog]')).to_have_count(0);assert page.evaluate('()=>fixture.state.drafts.body.text')=='retained';assert not errors,errors;checked('stale source retains the return draft without rebasing the original context');browser.close()
finally:server.shutdown()
record=dict(controlledRenderer=True,actualEngine=False,checks=checks,evidence=str(case));(case/'evidence.json').write_text(json.dumps(record,ensure_ascii=False,indent=2));print(json.dumps(record,ensure_ascii=False))
